{
  "name": "LabRAD Twisted连接组件",
  "name_en": "LabRAD Twisted Connection Component",
  "manufacturer": "",
  "description": "一个非物理的软件连接组件，用于与LabRAD管理器建立和维护同步连接、派生新连接、创建通信上下文，并向目标服务发送请求或消息。它主要用于实验控制软件中的服务发现、设置查询和进程间通信，而不是直接控制某台实体仪器。",
  "description_en": "A non-physical software connection component for establishing and maintaining a synchronous connection to a LabRAD manager, spawning new connections, creating communication contexts, and sending requests or messages to target services. It is mainly used for service discovery, setting inspection, and inter-process communication in lab automation software, rather than for direct control of a physical instrument.",
  "tag_hints": [
    "LabRAD manager connection",
    "Twisted networking",
    "service discovery",
    "request messaging",
    "experiment control software",
    "context management"
  ],
  "actions": [
    {
      "action_name": "auto-disconnect",
      "description": "断开与LabRAD管理器的连接。",
      "description_en": "Disconnect from the LabRAD manager."
    },
    {
      "action_name": "auto-spawn",
      "description": "派生一个连接到同一管理器的新独立连接。",
      "description_en": "Spawn a new independent connection to the same manager."
    },
    {
      "action_name": "auto-context",
      "description": "创建一个用于该连接的通信上下文。",
      "description_en": "Create a communication context for this connection."
    },
    {
      "action_name": "auto-sendRequest",
      "description": "向目标服务发送请求记录并等待响应。",
      "description_en": "Send request records to a target service and wait for a response."
    },
    {
      "action_name": "auto-sendMessage",
      "description": "向目标服务发送消息记录。",
      "description_en": "Send message records to a target service."
    },
    {
      "action_name": "auto-connected",
      "description": "获取连接状态。",
      "description_en": "get connection status"
    },
    {
      "action_name": "auto-getServersList",
      "description": "获取管理器中可用服务列表。",
      "description_en": "Get the list of available services from the manager."
    },
    {
      "action_name": "auto-getServerInfo",
      "description": "获取指定服务的信息。",
      "description_en": "Get information about a specified service."
    },
    {
      "action_name": "auto-getSettingsList",
      "description": "获取指定服务的设置列表。",
      "description_en": "Get the list of settings for a specified service."
    },
    {
      "action_name": "auto-getSettingInfo",
      "description": "获取指定设置的信息。",
      "description_en": "Get information about a specified setting."
    },
    {
      "action_name": "auto-getSettingInfoByName",
      "description": "按名称获取指定设置的信息。",
      "description_en": "Get information about a specified setting by name."
    }
  ]
}

